package pool

import "sync"

// Process doubles every item concurrently and returns the results
// (order not guaranteed).
func Process(items []int) []int {
	results := make(chan int)
	var wg sync.WaitGroup
	for _, it := range items {
		wg.Add(1)
		go func(v int) {
			defer wg.Done()
			results <- v * 2
		}(it)
	}
	wg.Wait()
	close(results)
	out := []int{}
	for r := range results {
		out = append(out, r)
	}
	return out
}

test_setup_files.pool_deadlock_test.go:
package pool

import (
	"sort"
	"testing"
)

func TestProcessAll(t *testing.T) {
	got := Process([]int{1, 2, 3, 4, 5, 6, 7, 8})
	sort.Ints(got)
	want := []int{2, 4, 6, 8, 10, 12, 14, 16}
	if len(got) != len(want) {
		t.Fatalf("got %d results, want %d: %v", len(got), len(want), got)
	}
	for i := range want {
		if got[i] != want[i] {
			t.Fatalf("sorted results = %v, want %v", got, want)
		}
	}
}

func TestProcessEmpty(t *testing.T) {
	if got := Process(nil); len(got) != 0 {
		t.Fatalf("Process(nil) = %v, want empty", got)
	}
}

